<?php
declare(strict_types=1);
require_once __DIR__.'/../includes/bootstrap.php';
if(!in_array('sqlite',PDO::getAvailableDrivers(),true)) {fwrite(STDERR,"SQLite PDO unavailable\n");exit(2);}
$db=new PDO('sqlite::memory:');$db->setAttribute(PDO::ATTR_ERRMODE,PDO::ERRMODE_EXCEPTION);$db->setAttribute(PDO::ATTR_DEFAULT_FETCH_MODE,PDO::FETCH_ASSOC);$db->exec('PRAGMA foreign_keys=ON');
$GLOBALS['az_database']=$db;
$db->exec('CREATE TABLE studio_schema(id INTEGER PRIMARY KEY,version INTEGER NOT NULL);INSERT INTO studio_schema VALUES(1,33)');
$db->exec('CREATE TABLE users(id INTEGER PRIMARY KEY,name TEXT,status TEXT NOT NULL)');
$db->exec('CREATE TABLE personal_media(id TEXT PRIMARY KEY,user_id INTEGER NOT NULL,duration_ms INTEGER NOT NULL,mime_type TEXT,title TEXT, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE)');
$db->exec('CREATE TABLE personal_edit_projects(id TEXT PRIMARY KEY,user_id INTEGER NOT NULL,title TEXT NOT NULL,timeline_json TEXT NOT NULL,revision INTEGER NOT NULL,created_at TEXT,updated_at TEXT, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE)');
$db->exec('CREATE TABLE agent_workspace_events(id TEXT PRIMARY KEY,recipient_id INTEGER,actor_id INTEGER,kind TEXT,title TEXT,detail TEXT,href TEXT,created_at TEXT,read_at TEXT,FOREIGN KEY(recipient_id) REFERENCES users(id) ON DELETE CASCADE)');
$db->exec('CREATE TABLE model_videos(id TEXT PRIMARY KEY,user_id INTEGER,status TEXT)');
$db->exec('CREATE TABLE production_projects(id TEXT PRIMARY KEY,owner_id INTEGER)');
$db->exec('CREATE TABLE production_edits(id TEXT PRIMARY KEY,project_id TEXT,owner_id INTEGER,status TEXT)');
$db->exec("INSERT INTO users VALUES(1,'Creator One','active'),(2,'Creator Two','active')");
az_upgrade_agent_video_schema($db);
$asserts=0;$ok=static function(bool $yes,string $label)use(&$asserts):void{$asserts++;if(!$yes)throw new RuntimeException('FAIL '.$label);};
$ok(az_schema_version($db)===34,'migrated to schema 34');
az_upgrade_agent_video_schema($db);$ok(az_schema_version($db)===34,'idempotent schema 34');
$sourceA=str_repeat('a',32);$sourceB=str_repeat('b',32);$project=str_repeat('c',32);$clipId=str_repeat('d',32);
$db->prepare('INSERT INTO personal_media VALUES(?,?,?,?,?)')->execute([$sourceA,1,12000,'video/mp4','Source One']);
$db->prepare('INSERT INTO personal_media VALUES(?,?,?,?,?)')->execute([$sourceB,2,12000,'video/mp4','Private Two']);
$original=['settings'=>['aspect'=>'16:9','fit'=>'contain','resolution'=>720,'fadeDuration'=>0.35,'cardDuration'=>2.5,'timedTitles'=>[],'detachedAudio'=>[], 'background'=>null],
  'clips'=>[['id'=>$clipId,'mediaId'=>$sourceA,'durationMs'=>12000,'trimStartMs'=>0,'trimEndMs'=>11000,'overlayText'=>'','overlayPosition'=>'bottom','titleCard'=>false,'volume'=>1,'audioDetached'=>false,'audioKeyframes'=>[],'filter'=>'none','transition'=>'cut']]];
$originalJson=json_encode($original,JSON_THROW_ON_ERROR);
$db->prepare('INSERT INTO personal_edit_projects VALUES(?,?,?,?,?,?,?)')->execute([$project,1,'Studio Edit',$originalJson,2,az_now(),az_now()]);
$note=az_video_agent_add_moment(['mediaId'=>$sourceA,'kind'=>'highlight','startMs'=>1000,'endMs'=>4500,'note'=>'My strongest section'],1);
$ok(az_valid_id($note['id']),'note inserted');
$ok(count(az_video_agent_moments(1))===1 && count(az_video_agent_moments(2))===0,'notes isolated');
$threw=false;try{az_video_agent_add_moment(['mediaId'=>$sourceB,'kind'=>'highlight','startMs'=>1000,'endMs'=>3000,'note'=>'Unauthorized'],1);}catch(AzHttpError $e){$threw=$e->status===404;}$ok($threw,'cannot annotate another owner source');
$stale=false;try{az_video_agent_generate(['projectId'=>$project,'revision'=>1,'goal'=>'highlight','targetSeconds'=>10],1);}catch(AzHttpError $e){$stale=$e->status===409;}$ok($stale,'must generate at current edit revision');
$plan=az_video_agent_generate(['projectId'=>$project,'revision'=>2,'goal'=>'highlight','targetSeconds'=>10],1);
$ok($plan['status']==='proposed'&&count($plan['proposal']['timeline']['clips'])===1,'plan created');
$ok(count(az_video_agent_plans(1,$project))===1,'owner can list');
$unauthorized=false;try{az_video_agent_plan_row($plan['id'],2);}catch(AzHttpError $e){$unauthorized=$e->status===404;}$ok($unauthorized,'other creator cannot open plan');
$notApproved=false;try{az_video_agent_apply(['planId'=>$plan['id']],1);}catch(AzHttpError $e){$notApproved=$e->errorCode==='approval_required';}$ok($notApproved,'explicit confirmation required');
$result=az_video_agent_apply(['planId'=>$plan['id'],'approve'=>true],1);
$ok($result['project']['revision']===3&&$result['plan']['status']==='applied','save verified plan');
$ok($result['project']['timeline']['clips'][0]['trimStartMs']===1000,'trim uses creator note');
$ok($db->query('SELECT COUNT(*) FROM personal_media')->fetchColumn()==2,'media untouched by editing');
$reject=false;try{az_video_agent_apply(['planId'=>$plan['id'],'approve'=>true],1);}catch(AzHttpError $e){$reject=$e->status===409;}$ok($reject,'cannot apply twice');
$before=az_video_agent_plan_row($plan['id'],1);$ok($before['status']==='applied','plan persisted');
$restored=az_video_agent_revert(['planId'=>$plan['id']],1);
$ok($restored['project']['revision']===4&&$restored['plan']['status']==='reverted','restore recorded as revision 4');
$ok($restored['project']['timeline']['clips'][0]['trimStartMs']===0,'restored original range');
$new=az_video_agent_generate(['projectId'=>$project,'revision'=>4,'goal'=>'teaser','targetSeconds'=>6],1);
$discarded=az_video_agent_discard(['planId'=>$new['id']],1);
$ok($discarded['status']==='discarded','explicit discard');
$cannotApply=false;try{az_video_agent_apply(['planId'=>$new['id'],'approve'=>true],1);}catch(AzHttpError $e){$cannotApply=$e->status===409;}$ok($cannotApply,'cannot apply discarded');
$next=az_video_agent_generate(['projectId'=>$project,'revision'=>4,'goal'=>'teaser','targetSeconds'=>6],1);
$newOwner=az_personal_edit_project_row($project,1);
az_personal_edit_project_save(['id'=>$project,'revision'=>4,'name'=>'New edit revision','timeline'=>json_decode($newOwner['timeline_json'],true)],1);
$cannotStale=false;try{az_video_agent_apply(['planId'=>$next['id'],'approve'=>true],1);}catch(AzHttpError $e){$cannotStale=$e->errorCode==='plan_stale';}$ok($cannotStale,'stale source cannot be overwritten');
$chat=az_video_agent_chat_snapshot(['id'=>1,'roles'=>['model']]);
$ok(isset($chat['counts']['videoPlansToReview']),'agent chat counts verified');
$ok(!str_contains(json_encode($chat),'My strongest section'),'no private source note leaked to AI chat');
$db->exec('DELETE FROM users WHERE id=1');
$ok($db->query('SELECT COUNT(*) FROM video_agent_plans')->fetchColumn()==0,'owner cascade removes plans');
$ok($db->query('SELECT COUNT(*) FROM video_agent_moments')->fetchColumn()==0,'owner cascade removes private moments');
echo "Video specialist PDO SQLite integration: $asserts passed\n";
